import type { DemoRecipe } from './recipes'

const hubOriginal = 'Hub Original — independently designed and implemented for Design Reference Hub. No upstream source code, brand assets, remote images, or remote fonts are included.'

const sectionBase = `main{container-type:inline-size;background:#f4f1e9;color:#171a18}.section-study{position:relative;width:min(92%,920px);max-height:92%;overflow:auto;border:1px solid #1d211d20;border-radius:24px;background:#fff;box-shadow:0 26px 70px #24271f18}.section-study button,.section-study input{font:inherit}.section-kicker{font-size:9px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.section-status{min-height:1.4em;font-size:10px;line-height:1.4}[data-variant=card] .section-study{width:100%;height:100%;max-height:none;border:0;border-radius:0;box-shadow:none}[data-variant=card] .section-status{display:none}@container(max-width:520px){.section-study{width:96%;border-radius:18px}}`

const cardTimer = (body: string, delay = 2200) => `let previewTimer=0;function previewTick(){${body}}function syncPreview(){clearInterval(previewTimer);previewTimer=0;if(document.querySelector('main').dataset.variant==='card'&&!reduced.matches&&!document.hidden)previewTimer=setInterval(previewTick,${delay})}reduced.addEventListener('change',syncPreview);document.addEventListener('visibilitychange',syncPreview);syncPreview();window.addEventListener('pagehide',()=>{clearInterval(previewTimer);reduced.removeEventListener('change',syncPreview);document.removeEventListener('visibilitychange',syncPreview)},{once:true});`

