    js: `const header=document.querySelector('.hero-study header'),menu=document.querySelector('.hero-menu'),status=document.querySelector('.section-status');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));header.classList.toggle('open',open)});document.querySelector('.hero-primary').addEventListener('click',()=>{status.textContent='Workspace opened in demo mode.';document.querySelector('.decision-card').animate([{transform:'translateY(8px)',opacity:.4},{transform:'none',opacity:1}],{duration:420,easing:'cubic-bezier(.2,.8,.2,1)'})});document.querySelector('.hero-secondary').addEventListener('click',()=>status.textContent='58-second product story queued — demo only.');`,
    logic: 'An editorial lime hero pairs one focused value proposition with a complete product-canvas proof panel. The responsive menu exposes real navigation links and maintains aria-expanded. Primary and secondary actions update a live status; the primary also animates the decision card once. The mobile layout stacks copy and product evidence rather than hiding the product.',
